CREATE TABLE recommendations(id uuid PRIMARY KEY,owner_id uuid NOT NULL,category varchar(64) NOT NULL CHECK(category ~ '^[A-Z][A-Z0-9_]{1,63}$'),title_ciphertext bytea NOT NULL,summary_ciphertext bytea NOT NULL,rationale_ciphertext bytea NOT NULL,status varchar(16) NOT NULL CHECK(status IN('AVAILABLE','ACCEPTED','REJECTED','DISMISSED','IGNORED','EXPIRED')),confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1),available_at timestamptz(3) NOT NULL,expires_at timestamptz(3),permission_policy_ref varchar(128) NOT NULL CHECK(length(permission_policy_ref)>0),permission_version integer NOT NULL CHECK(permission_version>0),provenance jsonb NOT NULL,created_at timestamptz(3) NOT NULL,updated_at timestamptz(3) NOT NULL,deleted_at timestamptz(3),purge_after timestamptz(3),version integer NOT NULL CHECK(version>0),CHECK(expires_at IS NULL OR expires_at>available_at));
CREATE INDEX recommendations_owner_status_available ON recommendations(owner_id,status,available_at DESC,id DESC) WHERE deleted_at IS NULL; CREATE INDEX recommendations_expiry ON recommendations(status,expires_at) WHERE deleted_at IS NULL;
CREATE TABLE recommendation_scores(id uuid PRIMARY KEY,recommendation_id uuid NOT NULL REFERENCES recommendations(id) ON DELETE CASCADE,factor varchar(32) NOT NULL CHECK(factor IN('SAFETY','EDUCATIONAL_VALUE','RELEVANCE','USER_INTEREST','TIMING','ACCESSIBILITY','CONFIDENCE','URGENCY')),score numeric(4,3) NOT NULL CHECK(score BETWEEN 0 AND 1),source_version integer NOT NULL CHECK(source_version>0),created_at timestamptz(3) NOT NULL,UNIQUE(recommendation_id,factor));
CREATE TABLE recommendation_history(id uuid PRIMARY KEY,recommendation_id uuid NOT NULL REFERENCES recommendations(id) ON DELETE CASCADE,owner_id uuid NOT NULL,from_status varchar(16),to_status varchar(16) NOT NULL,actor_type varchar(16) NOT NULL CHECK(actor_type IN('USER','SYSTEM','SERVICE')),actor_id uuid,reason_code varchar(64),event_id uuid NOT NULL UNIQUE,occurred_at timestamptz(3) NOT NULL,subject_version integer NOT NULL CHECK(subject_version>0),UNIQUE(recommendation_id,subject_version));
CREATE TABLE outbox_events(event_id uuid PRIMARY KEY,event_type varchar(128) NOT NULL,event_version integer NOT NULL CHECK(event_version>0),subject_type varchar(64) NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL CHECK(subject_version>0),partition_key varchar(128) NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz(3) NOT NULL,available_at timestamptz(3) NOT NULL,published_at timestamptz(3),attempt_count integer NOT NULL DEFAULT 0,last_error_code varchar(64),created_at timestamptz(3) NOT NULL); CREATE INDEX outbox_available ON outbox_events(available_at,event_id);
CREATE TABLE inbox_events(consumer_name varchar(64) NOT NULL,event_id uuid NOT NULL,subject_id uuid NOT NULL,subject_version integer NOT NULL,received_at timestamptz(3) NOT NULL,processed_at timestamptz(3),result_code varchar(64) NOT NULL,PRIMARY KEY(consumer_name,event_id));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY,original_event_id uuid NOT NULL,consumer_name varchar(64) NOT NULL,event_type varchar(128) NOT NULL,event_version integer NOT NULL,payload bytea NOT NULL,failure_code varchar(64) NOT NULL,attempt_count integer NOT NULL,first_failed_at timestamptz(3) NOT NULL,last_failed_at timestamptz(3) NOT NULL,resolved_at timestamptz(3),expires_at timestamptz(3) NOT NULL);
CREATE TABLE idempotency_records(id uuid PRIMARY KEY,environment varchar(32) NOT NULL,principal_id uuid NOT NULL,service varchar(64) NOT NULL,method varchar(16) NOT NULL,route_template varchar(256) NOT NULL,key_hash varchar(64) NOT NULL,request_hash varchar(64) NOT NULL,state varchar(16) NOT NULL CHECK(state IN('IN_PROGRESS','COMPLETED')),response_status integer,response_body bytea,response_headers jsonb,created_at timestamptz(3) NOT NULL,completed_at timestamptz(3),expires_at timestamptz(3) NOT NULL,UNIQUE(environment,principal_id,service,method,route_template,key_hash));
